package com.procurement.rfq.entity; import com.procurement.product.entity.Product; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="rfq_lines",uniqueConstraints=@UniqueConstraint(columnNames={"rfq_id","product_id"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class RfqLine{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="rfq_line_id") private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="rfq_id",nullable=false) private Rfq rfq; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(nullable=false,precision=15,scale=3) private BigDecimal quantity; @Column(name="required_date",nullable=false) private LocalDate requiredDate; @Column(name="estimated_unit_price",nullable=false,precision=15,scale=2) private BigDecimal estimatedUnitPrice; @Column(length=500) private String remarks; }
